export class Effects{
 constructor(){this.items=[];this.waves=[];this.shake=0;this.flash=0;this.hitstop=0;this.cameraX=0;this.cameraY=0;this.wavesCreated=0}
 burst(x,y,color,count=12,type='spark'){for(let i=0;i<count&&this.items.length<260;i++){const a=Math.random()*Math.PI*2,s=(type==='fire'||type==='lightning'?110:55)+Math.random()*240;this.items.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s-(type==='fire'?110:35),life:.22+Math.random()*.42,max:.64,size:2+Math.random()*4,color,type,seed:Math.random()*10})}}
 impact(x,y,type,character){const palette=character.id==='ryken'?['#fff1b5','#ffad42','#f04b32']:['#f3ffff','#8deeff','#358bff'];const style=type.includes('lightning')||type==='electric'?'lightning':type==='slash'?'slash':type.includes('fire')||type.includes('impact')?'fire':'spark';this.burst(x,y,palette[0],style==='lightning'?18:style==='slash'?14:20,style);if(type.includes('impact')||type==='launcher'||type.includes('ultimate')||type.includes('fire'))this.waves.push({x,y,color:palette[1],r:8,life:.32,max:.32});this.wavesCreated++;if(type.includes('ultimate')){this.flash=Math.max(this.flash,.5);for(let i=0;i<4;i++)this.waves.push({x,y,color:palette[i%3],r:4+i*6,life:.42,max:.42})}}
 update(dt){for(const e of this.items){e.life-=dt;e.x+=e.vx*dt;e.y+=e.vy*dt;e.vy+=(e.type==='fire'?-150:e.type==='lightning'?50:380)*dt}this.items=this.items.filter(e=>e.life>0);for(const w of this.waves){w.life-=dt;w.r+=300*dt}this.waves=this.waves.filter(w=>w.life>0);this.shake=Math.max(0,this.shake-dt*26);this.flash=Math.max(0,this.flash-dt*2.6);this.hitstop=Math.max(0,this.hitstop-dt)}
 draw(ctx){for(const w of this.waves){ctx.globalAlpha=Math.max(0,w.life/w.max);ctx.strokeStyle=w.color;ctx.lineWidth=2+(w.life/w.max)*2;ctx.beginPath();ctx.ellipse(w.x,w.y,w.r,w.r*.32,0,0,Math.PI*2);ctx.stroke()}for(const e of this.items){const alpha=Math.max(0,e.life/e.max);ctx.globalAlpha=alpha;ctx.fillStyle=e.color;if(e.type==='slash'){ctx.strokeStyle=e.color;ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(e.x,e.y);ctx.lineTo(e.x+e.vx*.12,e.y+e.vy*.12);ctx.stroke()}else if(e.type==='lightning'){ctx.strokeStyle=e.color;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(e.x,e.y);ctx.lineTo(e.x+e.size,e.y-5);ctx.lineTo(e.x-e.size,e.y-10);ctx.lineTo(e.x+e.size*2,e.y-17);ctx.stroke()}else if(e.type==='fire'){ctx.fillRect(Math.round(e.x),Math.round(e.y),Math.ceil(e.size*.8),Math.ceil(e.size*1.8))}else if(e.type==='speed'){ctx.fillRect(e.x,e.y,e.size*4,2)}else ctx.fillRect(e.x,e.y,e.size,e.size)}ctx.globalAlpha=1;ctx.shadowBlur=0}
}
